        if (!name || !form) return;
        const k = TPL_SPEC_KINDS.find(x => key.endsWith('::' + x.kind));
        const font = form.querySelector('[data-f=font]').value.trim();
        const hex = v => { v = String(v || '').trim(); return /^#?([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(v) ? (v[0] === '#' ? v : '#' + v).toLowerCase() : ''; };
