        const bad = ['colour', 'hl'].map(f => form.querySelector(`[data-f=${f}]`)).find(el => el.value.trim() && !hex(el.value) && !(el.dataset.f === 'hl' && form.querySelector('[data-f=nohl]').checked));
        if (bad) { bad.setCustomValidity('Use a colour code, like the ones the picker gives'); bad.reportValidity(); bad.oninput = () => bad.setCustomValidity(''); return; }
        const colour = hex(form.querySelector('[data-f=colour]').value);
