                <button type="button" class="tpl-brain-send" data-k="${_tplEscAttr(key)}" onclick="tplSpecSave(this.dataset.k)"${st === 'sending' ? ' disabled' : ''}>${st === 'sending' ? 'Saving…' : 'Save'}</button>
