        if (colour) { const h = colour.length === 4 ? colour.slice(1).split('').map(c => c + c).join('') : colour.slice(1); lum = (0.299 * parseInt(h.slice(0, 2), 16) + 0.587 * parseInt(h.slice(2, 4), 16) + 0.114 * parseInt(h.slice(4, 6), 16)) / 255; }
        const shadow = v.shadow && !/^(none|no)\b/i.test(v.shadow);
