            if (ids.some(i => theirIds.indexOf(i) >= 0)) return p;
            const theirLinks = [p.linear_issue_id, p.graphic_linear_issue_id].map(v => String(v || '').trim()).filter(Boolean);
            if (links.some(l => theirLinks.indexOf(l) >= 0)) return p;
