            const rows = await _arxRest(k.eventTable + '?select=' + k.eventKey + ',ts,actor,role&client=eq.' + encodeURIComponent(slug)
                + '&action=eq.archive&' + k.eventKey + '=in.(' + encodeURIComponent(list) + ')&order=ts.desc&limit=' + (ids.length * 3));
