                    e.stopPropagation();
                    if (e.key === 'Tab') { e.preventDefault(); return; }
                    if (e.key === 'Escape') { e.preventDefault(); _prodClearLayer(); return; }
                    if (e.key === 'ArrowDown') { e.preventDefault(); hi(sel < 0 ? 0 : sel + 1, 1); return; }
